  static const templates = <PixelPictureTemplate>[
    redPotion,
    strawberry,
    goldenKey,
    castle,
    sailingShip,
  ];

  static PixelPictureTemplate byId(String id) => templates.firstWhere(
    (template) => template.id == id,
    orElse: () => throw StateError('Unknown large-grid test template: $id'),
  );

  static LevelDefinition levelFor(PixelPictureTemplate template) {
    final score = PixelPictureDifficultyEvaluator.evaluate(template).score;
    const difficulty = LevelDifficulty.hard;
    const tile = LevelTileDefinition(id: 'debug_tile', colorValue: 0xff000000);
    return LevelDefinition(
      id: 'debug_level_${template.id}',
      number: 1,
      nameKey: template.id,
      boardSize: 1,
      difficulty: difficulty,
      difficultyScore: score.clamp(56, 80),
      puzzleType: JourneyPuzzleType.pixelPicture,
      pictureTemplateId: template.id,
      tiles: const [tile],
      initialTileOrder: const ['debug_tile'],
      solutionTileOrder: const ['debug_tile'],
    );
  }
